CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,display_name VARCHAR(40) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE ems_asset (id BIGINT PRIMARY KEY AUTO_INCREMENT,asset_code VARCHAR(32) NOT NULL UNIQUE,asset_name VARCHAR(100) NOT NULL,category VARCHAR(40) NOT NULL,location VARCHAR(80) NOT NULL,custodian VARCHAR(40) NOT NULL,original_value DECIMAL(14,2) NOT NULL,commissioned_on DATE NOT NULL,health_status VARCHAR(24) NOT NULL,operation_status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE ems_spare_part (id BIGINT PRIMARY KEY AUTO_INCREMENT,part_code VARCHAR(32) NOT NULL UNIQUE,part_name VARCHAR(100) NOT NULL,specification VARCHAR(60) NOT NULL,unit VARCHAR(20) NOT NULL,stock_quantity INT NOT NULL,safety_stock INT NOT NULL,warehouse VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE ems_maintenance_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_no VARCHAR(32) NOT NULL UNIQUE,asset_code VARCHAR(32) NOT NULL,plan_name VARCHAR(100) NOT NULL,cycle_days INT NOT NULL,next_execution_date DATE NOT NULL,team VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE ems_work_order (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(32) NOT NULL UNIQUE,asset_code VARCHAR(32) NOT NULL,title VARCHAR(140) NOT NULL,order_type VARCHAR(24) NOT NULL,priority VARCHAR(16) NOT NULL,assignee VARCHAR(40) NOT NULL,due_at DATETIME NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE ems_inspection_record (id BIGINT PRIMARY KEY AUTO_INCREMENT,record_no VARCHAR(32) NOT NULL UNIQUE,asset_code VARCHAR(32) NOT NULL,inspector VARCHAR(40) NOT NULL,inspected_at DATETIME NOT NULL,result VARCHAR(24) NOT NULL,finding VARCHAR(240) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE INDEX idx_ems_asset_health ON ems_asset(health_status); CREATE INDEX idx_ems_plan_date ON ems_maintenance_plan(next_execution_date); CREATE INDEX idx_ems_order_status ON ems_work_order(status); CREATE INDEX idx_ems_inspection_asset ON ems_inspection_record(asset_code);
